"""Reproject an accepted complete native source to an existing wardrobe pose. No image textures or image transforms."""
import bpy,sys,json,math,hashlib
from pathlib import Path
job=json.loads(Path(sys.argv[sys.argv.index('--')+1]).read_text());source=Path(job['sourceBlend']);bpy.ops.wm.open_mainfile(filepath=str(source));scene=bpy.context.scene;cam=scene.camera;px=scene.render.resolution_y/cam.data.ortho_scale;s=job['scale'];tx,ty=job['translate'];tyext=ty+256*(1-s);before={'location':list(cam.location),'orthoScale':cam.data.ortho_scale};cam.location.x+=((1-s)*512-tx)/(s*px);cam.location.z+=((s-1)*896+tyext)/(s*px);cam.data.ortho_scale/=s;scene['projection_source_sha256']=hashlib.sha256(source.read_bytes()).hexdigest();scene['projection_avatar']=job['avatar'];scene['projection_skin']=job['skin'];scene['projection_scale']=s;scene['projection_translate']=job['translate'];scene.render.filepath=job['outputPNG'];Path(scene.render.filepath).parent.mkdir(parents=True,exist_ok=True);bpy.ops.wm.save_as_mainfile(filepath=job['outputBlend']);bpy.ops.render.render(write_still=True);Path(job['outputMetadata']).write_text(json.dumps({**job,'cameraBefore':before,'cameraAfter':{'location':list(cam.location),'orthoScale':cam.data.ortho_scale},'sourceBlendSHA256':scene['projection_source_sha256'],'outputPNGSHA256':hashlib.sha256(Path(scene.render.filepath).read_bytes()).hexdigest(),'imageTextures':[(o.name,n.image.name) for o in bpy.data.materials if o.use_nodes for n in o.node_tree.nodes if n.type=='TEX_IMAGE' and n.image]},indent=2)+'\n')
